<?php
session_start(); require_once 'GEX-EC-05-SCRUM-Sprint-2-Desarrollo-ConfiguracionDeConexion-20261005-V1.0.php';
if (!isset($_SESSION['usuario_id'])) { header('Location: GEX-EC-05-SCRUM-Sprint-2-Desarrollo-InicioDeSesion-20261005-V1.0.php'); exit(); }
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: filter_input(INPUT_POST, 'solicitud_id', FILTER_VALIDATE_INT);
if (!$id) { header('Location: GEX-EC-05-SCRUM-Sprint-2-Desarrollo-ListaDeSolicitudes-20261005-V1.0.php'); exit(); }
$mensaje = ''; $mensajeError = '';
$stmt = $pdo->prepare('SELECT id, titulo, descripcion, categoria, estado, prioridad, justificacion_prioridad, fecha_objetivo, fecha_creacion, fecha_actualizacion, agente_id FROM solicitudes WHERE id = ? AND usuario_id = ?');
$stmt->execute([$id, $_SESSION['usuario_id']]); $solicitud = $stmt->fetch(PDO::FETCH_ASSOC);
if (!$solicitud) { http_response_code(404); $mensajeError = 'La solicitud no existe o no pertenece a tu cuenta.'; }
if ($_SERVER['REQUEST_METHOD'] === 'POST' && $solicitud) {
    $accion = $_POST['accion'] ?? ''; $motivo = trim($_POST['motivo'] ?? '');
    $nuevoEstado = $accion === 'confirmar' ? 'Cerrada' : ($accion === 'reabrir' ? 'En Proceso' : '');
    if (!in_array($accion, ['confirmar', 'reabrir'], true) || $solicitud['estado'] !== 'Resuelta' || ($accion === 'reabrir' && $motivo === '')) { $mensajeError = $accion === 'reabrir' ? 'Para reabrir debes indicar un motivo.' : 'La acción no está permitida para el estado actual.'; }
    else {
        $pdo->beginTransaction();
        try {
            $stmt = $pdo->prepare('UPDATE solicitudes SET estado = ? WHERE id = ? AND usuario_id = ?'); $stmt->execute([$nuevoEstado, $id, $_SESSION['usuario_id']]);
            $stmt = $pdo->prepare("INSERT INTO historial_estados (solicitud_id, usuario_id, rol, estado_anterior, estado_nuevo, motivo) VALUES (?, ?, 'Solicitante', 'Resuelta', ?, ?)"); $stmt->execute([$id, $_SESSION['usuario_id'], $nuevoEstado, $motivo ?: 'Solución confirmada por el solicitante.']);
            if (!empty($solicitud['agente_id'])) { $stmt = $pdo->prepare("INSERT INTO notificaciones (usuario_id, solicitud_id, tipo, mensaje) VALUES (?, ?, 'solucion', ?)"); $stmt->execute([$solicitud['agente_id'], $id, 'La solicitud #' . $id . ($accion === 'confirmar' ? ' fue confirmada y cerrada.' : ' fue reabierta: ' . $motivo)]); }
            $pdo->commit(); $mensaje = $accion === 'confirmar' ? 'Solución confirmada. La solicitud fue cerrada.' : 'Solicitud reabierta y enviada nuevamente a atención.';
        } catch (Throwable $e) { $pdo->rollBack(); $mensajeError = 'No fue posible registrar la acción.'; }
        $stmt = $pdo->prepare('SELECT id, titulo, descripcion, categoria, estado, prioridad, justificacion_prioridad, fecha_objetivo, fecha_creacion, fecha_actualizacion, agente_id FROM solicitudes WHERE id = ? AND usuario_id = ?'); $stmt->execute([$id, $_SESSION['usuario_id']]); $solicitud = $stmt->fetch(PDO::FETCH_ASSOC);
    }
}
$comentarios = []; $historial = [];
if ($solicitud) {
    $stmt = $pdo->prepare('SELECT c.comentario, c.fecha_creacion, u.nombre FROM comentarios_trabajo c INNER JOIN usuarios u ON u.id = c.agente_id WHERE c.solicitud_id = ? ORDER BY c.fecha_creacion DESC'); $stmt->execute([$id]); $comentarios = $stmt->fetchAll(PDO::FETCH_ASSOC);
    $stmt = $pdo->prepare('SELECT estado_anterior, estado_nuevo, motivo, fecha_cambio, u.nombre FROM historial_estados h INNER JOIN usuarios u ON u.id = h.usuario_id WHERE h.solicitud_id = ? ORDER BY h.fecha_cambio DESC'); $stmt->execute([$id]); $historial = $stmt->fetchAll(PDO::FETCH_ASSOC);
}
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Detalle de solicitud - Soporte</title><link rel="stylesheet" href="GEX-EC-05-SCRUM-Sprint-2-Desarrollo-EstilosDeInterfaz-20261005-V1.0.css"></head><body><div class="dashboard-layout"><?php include 'GEX-EC-05-SCRUM-Sprint-2-Desarrollo-MenuDeNavegacion-20261005-V1.0.php'; ?><div class="main-wrapper"><header class="topbar"><div class="topbar-title"><h2>Detalle de solicitud</h2></div><div class="topbar-user"><span><strong><?php echo htmlspecialchars($_SESSION['usuario_nombre']); ?></strong></span><span class="user-badge"><?php echo htmlspecialchars($_SESSION['usuario_rol']); ?></span><a href="GEX-EC-05-SCRUM-Sprint-2-Desarrollo-CierreDeSesion-20261005-V1.0.php" class="btn-logout">Cerrar Sesión</a></div></header><main class="content-area"><a href="GEX-EC-05-SCRUM-Sprint-2-Desarrollo-ListaDeSolicitudes-20261005-V1.0.php" class="back-link">← Volver a mis solicitudes</a>
<?php if (!$solicitud): ?><div class="ui-card detail-card"><h1>Solicitud no encontrada</h1><p><?php echo htmlspecialchars($mensajeError); ?></p></div><?php else: ?>
<?php if ($mensaje): ?><div class="notice-success"><?php echo htmlspecialchars($mensaje); ?></div><?php endif; ?><?php if ($mensajeError): ?><div class="notice-error"><?php echo htmlspecialchars($mensajeError); ?></div><?php endif; ?>
<div class="ui-card detail-card"><div class="detail-header"><div><span class="detail-id">Solicitud #<?php echo (int) $solicitud['id']; ?></span><h1><?php echo htmlspecialchars($solicitud['titulo']); ?></h1></div><span class="status-badge status-<?php echo strtolower(str_replace(' ', '-', $solicitud['estado'])); ?>"><?php echo htmlspecialchars($solicitud['estado']); ?></span></div><div class="detail-grid"><div><span class="detail-label">Categoría</span><strong><?php echo htmlspecialchars($solicitud['categoria']); ?></strong></div><div><span class="detail-label">Prioridad</span><strong><?php echo htmlspecialchars($solicitud['prioridad']); ?></strong></div><div><span class="detail-label">Última actualización</span><strong><?php echo htmlspecialchars(date('d/m/Y H:i', strtotime($solicitud['fecha_actualizacion']))); ?></strong></div></div><?php if ($solicitud['prioridad'] === 'Alta'): ?><div class="priority-requirements"><span class="detail-label">Justificación de prioridad alta</span><p><?php echo nl2br(htmlspecialchars($solicitud['justificacion_prioridad'] ?? '')); ?></p><span class="detail-label">Fecha objetivo</span><strong><?php echo htmlspecialchars($solicitud['fecha_objetivo'] ? date('d/m/Y', strtotime($solicitud['fecha_objetivo'])) : 'No definida'); ?></strong></div><?php endif; ?><div class="description-block"><span class="detail-label">Descripción</span><p><?php echo nl2br(htmlspecialchars($solicitud['descripcion'])); ?></p></div>
<?php if ($solicitud['estado'] === 'Resuelta'): ?><div class="resolution-actions"><h3>Revisión de la solución</h3><p>Confirma si la solución resolvió el inconveniente o reabre la solicitud indicando el motivo.</p><form method="POST"><input type="hidden" name="solicitud_id" value="<?php echo (int) $id; ?>"><button class="btn-primary-link" name="accion" value="confirmar">Confirmar solución</button><textarea name="motivo" placeholder="Motivo si necesitas reabrirla"></textarea><button class="badge-btn" name="accion" value="reabrir">Reabrir solicitud</button></form></div><?php endif; ?>
<hr><h3>Comentarios de trabajo</h3><?php if (!$comentarios): ?><p>No hay comentarios todavía.</p><?php else: ?><?php foreach ($comentarios as $c): ?><div class="comment-item"><strong><?php echo htmlspecialchars($c['nombre']); ?></strong><small><?php echo htmlspecialchars(date('d/m/Y H:i', strtotime($c['fecha_creacion']))); ?></small><p><?php echo nl2br(htmlspecialchars($c['comentario'])); ?></p></div><?php endforeach; ?><?php endif; ?><h3>Historial de estados</h3><?php foreach ($historial as $h): ?><div class="history-item"><strong><?php echo htmlspecialchars($h['estado_anterior'] ?: 'Inicio'); ?> → <?php echo htmlspecialchars($h['estado_nuevo']); ?></strong><small><?php echo htmlspecialchars($h['nombre']); ?> · <?php echo htmlspecialchars(date('d/m/Y H:i', strtotime($h['fecha_cambio']))); ?></small><?php if (!empty($h['motivo'])): ?><p><?php echo nl2br(htmlspecialchars($h['motivo'])); ?></p><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?></main></div></div></body></html>
